#!/usr/bin/env bash
set -euo pipefail
PUBLIC_DIR="$(cd -- "$(dirname -- "$0")" && pwd)"
RECOVERY_PYTHON="${CORPUS_PYTHON:-python3}"
PROJECT_VALIDATOR="${CORPUS_VALIDATOR:-/disks/sata1/yupeng/human-proof-corpus/repo/corpus-work/scripts/validate_corpus.py}"
DESTINATION="$1"
test ! -e "$DESTINATION"
"$RECOVERY_PYTHON" -c 'import hashlib,sys; from pathlib import Path; assert hashlib.sha256(Path(sys.argv[1]).read_bytes()).hexdigest()==sys.argv[2], "restore helper hash mismatch"' "$PUBLIC_DIR/helpers/restore_history.py" 01db7159b149c96a16678150303a33a4f7e9479b709e302a2bd0b4bbd509ea47
"$RECOVERY_PYTHON" -c 'import hashlib,json,sys; from pathlib import Path; base=Path(sys.argv[1]).resolve().parent; pins=json.loads(Path(sys.argv[2]).read_text())["project_gate_dependencies"]; assert all(hashlib.sha256((base/name).read_bytes()).hexdigest()==value for name,value in pins.items()), "project validator or policy dependency identity mismatch"' "$PROJECT_VALIDATOR" "$PUBLIC_DIR/PINS.json"
mkdir -p "$DESTINATION/reports"
"$RECOVERY_PYTHON" -B "$PUBLIC_DIR/helpers/restore_history.py" --manifest "$PUBLIC_DIR/packets/1475/materials.cas.manifest.json" --expected-manifest-sha256 22ed067254bae3489e72945cbb2a929f931944fc51204d97a57598bd9182ad48 --destination "$DESTINATION/1475"
"$RECOVERY_PYTHON" -B "$PROJECT_VALIDATOR" --mode editable-delivery --package "$DESTINATION/1475/package" --evidence "$DESTINATION/1475/package/delivery-evidence.json" --build-root "$DESTINATION/1475/build" --receipt-root "$DESTINATION/1475/receipts" --item 1475 --report "$DESTINATION/reports/1475-item.json"
"$RECOVERY_PYTHON" -B "$PROJECT_VALIDATOR" --mode editable-delivery --package "$DESTINATION/1475/package" --evidence "$DESTINATION/1475/package/delivery-evidence.json" --build-root "$DESTINATION/1475/build" --receipt-root "$DESTINATION/1475/receipts" --report "$DESTINATION/reports/1475-aggregate.json"
"$RECOVERY_PYTHON" -B "$PUBLIC_DIR/helpers/restore_history.py" --manifest "$PUBLIC_DIR/packets/1479/materials.cas.manifest.json" --expected-manifest-sha256 4e024111700ef2747d41d5d593320fb4f49222b586e6dffd32cea4d914764a97 --destination "$DESTINATION/1479"
"$RECOVERY_PYTHON" -B "$PROJECT_VALIDATOR" --mode editable-delivery --package "$DESTINATION/1479/package" --evidence "$DESTINATION/1479/package/delivery-evidence.json" --build-root "$DESTINATION/1479/build" --receipt-root "$DESTINATION/1479/receipts" --item 1479 --report "$DESTINATION/reports/1479-item.json"
